<div id="admin-disclosures-panel" class="admin-panel" role="tabpanel" aria-labelledby="tab-disclosures" hidden>
                        <div class="panel-header"><div><p class="eyebrow">Transparency publishing</p><h2>Post a disclosure</h2><p>Publish an official SK record to the public bulletin board.</p></div></div>
                        <div class="card full-width-card composer-card">
                            <form id="disclosure-form" novalidate data-action-submit="handlePostDisclosure(event)">
                                <div class="input-group"><label for="disc-category">Category <span class="req-star" aria-hidden="true">*</span></label><select id="disc-category" required aria-describedby="disc-category-error"><option value="" selected disabled>Select a category</option><option value="1">Announcements</option><option value="2">Financial Reports</option><option value="3">Projects &amp; Budget</option><option value="4">Meeting Minutes</option></select><span class="disclosure-field-error" id="disc-category-error" role="alert" hidden></span></div>
                                <div class="input-group"><label for="disc-title">Title <span class="req-star" aria-hidden="true">*</span></label><input type="text" id="disc-title" maxlength="120" required placeholder="Enter a clear title" aria-describedby="disc-title-counter disc-title-error"><span class="disclosure-char-count" id="disc-title-counter" aria-live="polite">0/120</span><span class="disclosure-field-error" id="disc-title-error" role="alert" hidden></span></div>
                                <div class="input-group"><label for="disc-content">Description <span class="req-star" aria-hidden="true">*</span></label><textarea id="disc-content" maxlength="2000" required rows="5" placeholder="Share the details residents need to know." aria-describedby="disc-content-counter disc-content-error"></textarea><span class="disclosure-char-count" id="disc-content-counter" aria-live="polite">0/2000</span><span class="disclosure-field-error" id="disc-content-error" role="alert" hidden></span></div>
                                <div class="input-group disclosure-file-group"><label for="disc-file">Attachment (optional)</label><div class="disclosure-dropzone" id="disc-dropzone"><i class="fas fa-cloud-arrow-up" aria-hidden="true"></i><p class="disclosure-dropzone-desktop-copy">Drag &amp; drop here, or <button type="button" class="disclosure-browse" data-action-click="openFilePicker('disc-file')">browse</button></p><p class="disclosure-dropzone-mobile-copy">Tap to choose a file</p><span>PDF, DOCX, JPG, or PNG · max 5 MB</span><input type="file" id="disc-file" accept=".pdf,.docx,.jpg,.jpeg,.png" aria-label="Add an optional disclosure attachment"></div><div class="disclosure-file-preview hidden" id="disc-file-preview"><img class="disclosure-file-thumbnail hidden" id="disc-file-thumbnail" alt="Attachment thumbnail"><i class="fas fa-file-lines" id="disc-file-icon" aria-hidden="true"></i><span id="disc-file-name"></span><small id="disc-file-size"></small><button type="button" class="disclosure-remove-file" data-action-click="clearDisclosureFile()">Remove</button></div><p class="disclosure-file-error" id="disc-file-error" role="alert" hidden></p><p class="disclosure-attachment-note hidden" id="disclosure-attachment-edit-note">The existing attachment stays unchanged while editing.</p></div>
                                <div class="disclosure-form-actions"><button type="button" class="btn-outline" id="save-disclosure-draft">Save as draft</button><button type="button" class="btn-outline" id="preview-disclosure-button">Preview</button><span class="disclosure-edit-actions hidden" id="disclosure-edit-actions"><button type="button" class="btn-outline" id="cancel-disclosure-edit">Cancel edit</button></span><button type="submit" class="btn-solid" id="publish-disclosure-button">Publish disclosure</button></div>
                                <p class="disclosure-status" id="disclosure-status" role="status" aria-live="polite" hidden></p>
                                <section class="disclosure-preview hidden" id="disclosure-preview" aria-label="Public bulletin preview"><p class="eyebrow">Public bulletin preview</p><div id="disclosure-preview-post"></div><div class="disclosure-preview-actions"><button type="button" class="btn-outline" id="disclosure-preview-back">Back to edit</button><button type="button" class="btn-solid" id="disclosure-preview-publish">Publish disclosure</button></div></section>
                            </form>
                        </div>
                        <section class="recent-disclosures" aria-labelledby="recent-disclosures-title"><div class="recent-disclosures-header"><div><p class="eyebrow">Published records</p><h3 id="recent-disclosures-title">Recent disclosures</h3></div></div><div class="card recent-disclosures-card"><div class="recent-disclosures-list" id="recent-disclosures-list" aria-live="polite"><p class="empty-state">Loading disclosures…</p></div></div></section>
                    </div>
                    
